use num_bigint::{BigUint as N,BigInt,ToBigInt};
use num_traits::{Zero,One,ToPrimitive};
use serde_json::{Value,json};
use std::{time::Instant,env};
#[derive(Clone)] enum Kind {Prime(N),Binary(usize,N),Odd(u32,u32)}
#[derive(Clone)] struct F {name:String,k:Kind}
type P=Vec<N>;
fn n(x:u32)->N{x.into()}
fn trim(mut a:P)->P {while a.last().is_some_and(N::is_zero){a.pop();}a}
impl F {
 fn characteristic(&self)->u32 {match self.k {Kind::Binary(..)=>2,Kind::Odd(p,_)=>p,Kind::Prime(ref p)=>p.to_u32().unwrap_or(0)}}
 fn order(&self)->N {match &self.k {Kind::Prime(p)=>p.clone(),Kind::Binary(d,_)=>N::one()<<d,Kind::Odd(p,_)=>n(p*p)}}
 fn scalar(&self,i:usize)->N {match &self.k{Kind::Prime(p)=>N::from(i)%p,Kind::Binary(..)=>n((i%2)as u32),Kind::Odd(p,_)=>n((i%(*p as usize))as u32)}}
 fn add(&self,a:&N,b:&N)->N {match &self.k{Kind::Prime(p)=>(a+b)%p,Kind::Binary(..)=>a^b,Kind::Odd(p,_)=>{let a=a.to_u32().unwrap();let b=b.to_u32().unwrap();n(((a%p+b%p)%p)+p*((a/p+b/p)%p))}}}
 fn neg(&self,a:&N)->N {match &self.k{Kind::Prime(p)=>if a.is_zero(){n(0)}else{p-a},Kind::Binary(..)=>a.clone(),Kind::Odd(p,_)=>{let a=a.to_u32().unwrap();n((p-a%p)%p+p*((p-a/p)%p))}}}
 fn sub(&self,a:&N,b:&N)->N {self.add(a,&self.neg(b))}
 fn mul(&self,a:&N,b:&N)->N {match &self.k{
  Kind::Prime(p)=>(a*b)%p,
  Kind::Binary(d,m)=>{let mut a=a.clone();let mut b=b.clone();let mut c=n(0);while !b.is_zero(){if b.bit(0){c^=&a;}b>>=1;a<<=1;if a.bit(*d as u64){a^=m;}}c},
  Kind::Odd(p,c)=>{let a=a.to_u32().unwrap();let b=b.to_u32().unwrap();let u=(a%p)*(b%p);let v=(*c)*(a/p)*(b/p);n((u+p*p*p-v)%p+p*(((a%p)*(b/p)+(a/p)*(b%p))%p))}
 }}
 fn pow(&self,a:&N,mut e:N)->N {let mut x=a.clone();let mut y=n(1);while !e.is_zero(){if e.bit(0){y=self.mul(&y,&x);}e>>=1;if !e.is_zero(){x=self.mul(&x,&x);}}y}
 fn inv(&self,a:&N)->N {assert!(!a.is_zero());match &self.k{
  Kind::Binary(_,m)=>{let(mut u,mut v,mut g,mut h)=(a.clone(),m.clone(),n(1),n(0));while u!=n(1){assert!(!u.is_zero());if u.bits()<v.bits(){std::mem::swap(&mut u,&mut v);std::mem::swap(&mut g,&mut h);}let j=(u.bits()-v.bits())as usize;u^=&v<<j;g^=&h<<j;}while g.bits()>=m.bits(){let j=(g.bits()-m.bits())as usize;g^=m<<j;}g},
  Kind::Prime(p)=>{let(mut r,mut s)=(p.to_bigint().unwrap(),a.to_bigint().unwrap());let(mut u,mut v)=(BigInt::zero(),BigInt::one());while !s.is_zero(){let q=&r/&s;(r,s)=(s.clone(),r-&q*&s);(u,v)=(v.clone(),u-q*v);}let p=p.to_bigint().unwrap();((u%&p+&p)%p).to_biguint().unwrap()},
  _=>self.pow(a,self.order()-n(2))
 }}
 fn rem(&self,mut a:P,b:&P,pseudo:bool)->P {assert!(!b.is_empty());a=trim(a);let lc=b.last().unwrap();let inv=if !pseudo&&*lc!=n(1){self.inv(lc)}else{n(1)};while a.len()>=b.len()&&!a.is_empty(){let shift=a.len()-b.len();let top=a.last().unwrap().clone();let c=if pseudo{top}else{self.mul(&top,&inv)};if pseudo&&*lc!=n(1){a.iter_mut().for_each(|x|*x=self.mul(x,lc));}for(i,x)in b.iter().enumerate(){a[i+shift]=self.sub(&a[i+shift],&self.mul(&c,x));}a=trim(a);}a}
 fn mulp(&self,a:&P,b:&P)->P {if a.is_empty()||b.is_empty(){return vec![];}let mut c=vec![n(0);a.len()+b.len()-1];for(i,x)in a.iter().enumerate(){for(j,y)in b.iter().enumerate(){c[i+j]=self.add(&c[i+j],&self.mul(x,y));}}trim(c)}
 fn derivative(&self,h:&P)->P {trim(h.iter().enumerate().skip(1).map(|(i,c)|self.mul(&self.scalar(i),c)).collect())}
 fn sf(&self,h:&P,method:u32)->bool {if method==2&&self.characteristic()==2&&h.len()==6&&h[5]==n(1){let u=self.add(&h[2],&self.mul(&h[4],&h[3]));let v=self.add(&h[0],&self.mul(&h[4],&h[1]));let delta=self.add(&self.add(&self.mul(&v,&v),&self.mul(&h[3],&self.mul(&u,&v))),&self.mul(&h[1],&self.mul(&u,&u)));return !delta.is_zero();}let(mut a,mut b)=(h.clone(),self.derivative(h));while !b.is_empty(){let r=self.rem(a,&b,method!=0);a=b;b=r;}a.len()==1}
 fn product(&self,rs:&[N])->P {rs.iter().fold(vec![n(1)],|h,a|self.mulp(&h,&vec![self.neg(a),n(1)]))}
 fn support(&self,h:&P,l:&P,method:u32)->bool {let mut r=self.rem(l.clone(),h,false);if method>0&&self.sf(h,method){return r.is_empty();}let power=if self.characteristic()==2{8}else{5};let mut out=vec![n(1)];for _ in 0..power{out=self.rem(self.mulp(&out,&r),h,false);}r=out;r.is_empty()}
}
fn fields()->Vec<F>{let mut a=vec![];for p in [3,5,7,11]{a.push(F{name:format!("Fp{p}"),k:Kind::Prime(n(p))});}let one=N::one();for(d,p)in[(192,(&one<<192)-(&one<<64)-&one),(224,(&one<<224)-(&one<<96)+&one),(256,(&one<<256)-(&one<<224)+(&one<<192)+(&one<<96)-&one),(384,(&one<<384)-(&one<<128)-(&one<<96)+(&one<<32)-&one),(521,(&one<<521)-&one)]{a.push(F{name:format!("P{d}"),k:Kind::Prime(p)});}for(d,terms)in [(2,vec![1,0]),(3,vec![1,0]),(4,vec![1,0]),(83,vec![45,2,1,0]),(163,vec![7,6,3,0]),(233,vec![74,0]),(283,vec![12,7,5,0]),(409,vec![87,0]),(571,vec![10,5,2,0])]{let mut m=&one<<d;for i in terms{m|=&one<<i;}a.push(F{name:format!("GF2^{d}"),k:Kind::Binary(d,m)});}for(p,c)in[(3,1),(5,2)]{a.push(F{name:format!("GF{p}^2"),k:Kind::Odd(p,c)});}a}
fn oracle_sf(f:&F,h:&P)->bool{let q=f.order().to_usize().unwrap();for deg in 1..=2{for mut v in 0..q.pow(deg){let mut a=vec![];for _ in 0..deg{a.push(N::from(v%q));v/=q;}a.push(n(1));if f.rem(h.clone(),&f.mulp(&a,&a),false).is_empty(){return false;}}}true}
fn bgcd(mut a:N,mut b:N)->N{while !b.is_zero(){while !a.is_zero()&&a.bits()>=b.bits(){let j=(a.bits()-b.bits())as usize;a^=&b<<j;}std::mem::swap(&mut a,&mut b);}a}
fn field_controls(fs:&[F]){for f in fs{match &f.k{Kind::Binary(deg,m)=>{let mut z=n(2);let mut factors=vec![];let mut d=*deg;let mut r=2;while r*r<=d{if d%r==0{factors.push(r);while d%r==0{d/=r;}}r+=1;}if d>1{factors.push(d);}for i in 1..=*deg{z=f.mul(&z,&z);for r in &factors{if i==deg/r{assert_eq!(bgcd(&z^n(2),m.clone()),n(1),"Rabin {}",f.name);}}}assert_eq!(z,n(2),"Rabinfinal {}",f.name);},Kind::Odd(p,c)=>{for x in 0..*p{assert_ne!((x*x+c)%p,0);}},_=>{}}for x in 1u32..=7{let a=N::from(x)%f.order();if !a.is_zero(){assert_eq!(f.mul(&a,&f.inv(&a)),n(1));}}}}
fn oracle()->Value{let all=fields();field_controls(&all);let mut count=0;let mut support_count=0;for name in ["Fp3","Fp5","GF2^2"]{let f=all.iter().find(|f|f.name==name).unwrap();let q=f.order().to_usize().unwrap();let domain=vec![n(0),n(1)];let l=f.product(&domain);let allowed:Vec<P>=(0..=5).map(|k|{let rs=(0..5).map(|i|if i<k{n(1)}else{n(0)}).collect::<Vec<_>>();f.product(&rs)}).collect();for mut v in 0..q.pow(5){let mut h=vec![];for _ in 0..5{h.push(N::from(v%q));v/=q;}h.push(n(1));let expected=oracle_sf(f,&h);for method in 0..=2{assert_eq!(f.sf(&h,method),expected,"{} {:?}",f.name,h);assert_eq!(f.support(&h,&l,method),allowed.contains(&h));}count+=1;support_count+=1;}}json!({"status":"passed","independent_monic_quintics":count,"independent_support_cases":support_count,"characteristics":[2,3,5],"oracle":"no degree1/2 monic square divides H; literal domain-root products"})}
fn panel(seed:u64)->Value{let start=Instant::now();let mut state=seed;let mut rows=vec![];for f in fields(){let q=f.order();let mut hs=vec![];for i in 0..12{let mut roots=vec![];for j in 0..5{state^=state<<13;state^=state>>7;state^=state<<17;let v=if i<6{let mut wide=N::zero();for _ in 0..q.bits().div_ceil(64){state^=state<<13;state^=state>>7;state^=state<<17;wide=(wide<<64)+N::from(state);}wide}else{N::from((j%2)as u32)};roots.push(v%&q);}hs.push(f.product(&roots));}let mut times=vec![vec![],vec![],vec![]];let mut answers=vec![vec![],vec![],vec![]];for rep in 0..3{let methods=if rep%2==0{vec![0,1,2]}else{vec![2,1,0]};for method in methods{let t=Instant::now();let a:Vec<bool>=hs.iter().map(|h|f.sf(h,method)).collect();times[method as usize].push(t.elapsed().as_secs_f64());answers[method as usize]=a;}}assert_eq!(answers[0],answers[1]);assert_eq!(answers[0],answers[2]);rows.push(json!({"field":f.name,"seconds":times,"answers":answers[0],"polynomials":hs.iter().map(|h|h.iter().map(|x|x.to_str_radix(16)).collect::<Vec<_>>()).collect::<Vec<_>>(),"methods":["field_inverse_Euclid","fraction_free_PRS","binary_quintic_resultant_else_PRS"]}));assert!(start.elapsed().as_secs()<65,"panel deadline");}json!({"rows":rows,"distinct_fields":20,"seed":seed,"original_root_count_exact":null,"release_gate_claim":false,"scope":"squarefree classification only; not all-roots solving or qualified end-to-end timing"})}
fn main(){let args:Vec<_>=env::args().collect();if args.get(1).is_some_and(|x|x=="controls"){println!("{}",oracle());return;}let id=args.get(1).expect("experiment id");let seed=args.get(2).expect("seed").parse().unwrap();let start=Instant::now();let e=panel(seed);let mut result=json!({"schema":"scientific_result_v1","experiment_id":id,"status":"passed","summary":"Native inverse-free squarefree criteria agree with native Euclidean reference across20fields.","evidence":e,"next_actions":["Compare total support and all-roots pipelines before promotion; do not multiply stage gains.","IfPRSregresses reject blanketdispatch; preserve resultants as char2 specialization."]});let encoded=serde_json::to_string(&result).unwrap();if start.elapsed().as_secs()>=70{result["status"]=json!("inconclusive");result["summary"]=json!("late serialization");}println!("{}",if result["status"]=="passed"{encoded}else{result.to_string()});}
